const API_BASE = window.ESTERRA_API_BASE || '/api/esterra';
const state = { deal: 'buy', properties: [], selected: null };
const $ = (selector, root = document) => root.querySelector(selector);
const esc = value => String(value ?? '').replace(/[&<>"']/g, char => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[char]));
const money = (value, period) => `${Number(value).toLocaleString('ru-RU')} ₽${period === 'month' ? ' / мес.' : period === 'night' ? ' / ночь' : ''}`;
const dealName = type => ({ buy: 'покупка', long_rent: 'долгосрочная аренда', daily_rent: 'посуточно' }[type] || type);
function setStatus(message, kind = 'loading') { const status = $('#apiStatus'); status.dataset.kind = kind; status.querySelector('span').textContent = message; }
function queryParams() { const form = $('#searchForm'); const params = new URLSearchParams({ deal_type: state.deal }); const data = new FormData(form); for (const key of ['q', 'max_price', 'rooms']) if (data.get(key)) params.set(key, data.get(key)); return params; }
function card(property) { return `<article class="property-card"><button class="property-open" data-property="${property.id}" aria-label="Открыть ${esc(property.title)}"><div class="property-image"><img src="${esc(property.image_url)}" alt="${esc(property.title)}" loading="lazy" /><span class="property-deal">${esc(dealName(property.deal_type))}</span><span class="property-number">0${property.id}</span></div><div class="property-body"><p class="property-kicker">${esc(property.district)} · ${property.area_sqm} м²</p><h3>${esc(property.title)}</h3><p class="property-description">${esc(property.description)}</p><div class="property-foot"><strong>${money(property.price_rub, property.price_period)}</strong><span>Открыть ↗</span></div></div></button></article>`; }
async function loadProperties() { setStatus('Обновляем базу объектов…'); $('#propertyGrid').innerHTML = '<div class="loading-state">Загружаем доступные варианты<span></span></div>'; try { const response = await fetch(`${API_BASE}/properties?${queryParams()}`, { headers: { Accept: 'application/json' } }); if (!response.ok) throw new Error(`HTTP ${response.status}`); const payload = await response.json(); state.properties = payload.data || []; setStatus('База подключена · данные получены', 'ok'); $('#resultsCount').textContent = `${state.properties.length} объектов в подборке`; $('#propertyGrid').innerHTML = state.properties.map(card).join(''); $('#emptyState').hidden = state.properties.length > 0; } catch (error) { state.properties = []; $('#propertyGrid').innerHTML = ''; $('#emptyState').hidden = false; $('#emptyState').innerHTML = '<strong>База объектов сейчас недоступна.</strong><span>Запустите ESTERRA API или подключите production backend. Успешные заявки в этом состоянии не показываются.</span>'; $('#resultsCount').textContent = 'Источник данных недоступен'; setStatus('API не подключён · требуется настройка', 'error'); } }
function detail(property) { const amenities = (property.amenities || []).map(item => `<span>${esc(item)}</span>`).join(''); return `<div class="detail-layout"><div class="detail-image"><img src="${esc(property.image_url)}" alt="${esc(property.title)}" /></div><div class="detail-copy"><p class="eyebrow">${esc(dealName(property.deal_type))} / ${esc(property.district)}</p><h2>${esc(property.title)}</h2><p class="detail-address">${esc(property.address)}, ${esc(property.city)}</p><p>${esc(property.description)}</p><div class="detail-specs"><span><b>${property.area_sqm} м²</b>площадь</span><span><b>${property.rooms === 0 ? 'студия' : `${property.rooms} комн.`}</b>планировка</span><span><b>${money(property.price_rub, property.price_period)}</b>стоимость</span></div><div class="amenities">${amenities}</div><form class="inquiry-form" id="inquiryForm"><input type="hidden" name="propertyId" value="${property.id}" /><label>Имя<input name="name" autocomplete="name" required minlength="2" maxlength="80" placeholder="Как к вам обращаться?" /></label><label>Телефон<input name="phone" autocomplete="tel" required placeholder="+7 999 000-00-00" /></label><label>Email <span>(необязательно)</span><input name="email" type="email" autocomplete="email" placeholder="you@example.com" /></label><label>Сообщение<textarea name="message" maxlength="1000" placeholder="Что важно уточнить?"></textarea></label><label class="consent"><input name="consent" type="checkbox" required /> <span>Согласен на обработку заявки</span></label><div class="form-error" id="formError" role="alert"></div><button class="button button-dark" type="submit">Отправить заявку <span>↗</span></button></form></div></div>`; }
function openProperty(id) { const property = state.properties.find(item => item.id === Number(id)); if (!property) return; state.selected = property; $('#propertyDetail').innerHTML = detail(property); $('#propertyDialog').showModal(); $('#inquiryForm').addEventListener('submit', submitInquiry); }
async function submitInquiry(event) { event.preventDefault(); const form = event.currentTarget; const button = form.querySelector('button[type=submit]'); const error = $('#formError'); error.textContent = ''; button.disabled = true; button.textContent = 'Отправляем…'; const values = Object.fromEntries(new FormData(form)); values.propertyId = Number(values.propertyId); values.consent = form.elements.consent.checked; try { const response = await fetch(`${API_BASE}/inquiries`, { method: 'POST', headers: { 'Content-Type': 'application/json', Accept: 'application/json' }, body: JSON.stringify(values) }); const payload = await response.json(); if (!response.ok) { error.textContent = Object.values(payload.fields || {}).join(' ' ) || payload.error || 'Не удалось отправить заявку.'; return; } form.innerHTML = `<div class="success-state"><span>✓</span><h3>Заявка записана</h3><p>Номер заявки: <strong>#${payload.data.id}</strong>. Следующий шаг сохранён в базе ESTERRA.</p><button type="button" class="button button-dark" id="successClose">Вернуться к объектам</button></div>`; $('#successClose').addEventListener('click', () => $('#propertyDialog').close()); } catch { error.textContent = 'Сервис заявки недоступен. Проверьте подключение API.'; } finally { button.disabled = false; if (button.textContent === 'Отправляем…') button.innerHTML = 'Отправить заявку <span>↗</span>'; } }
document.addEventListener('DOMContentLoaded', () => { document.querySelectorAll('[data-deal]').forEach(button => button.addEventListener('click', () => { state.deal = button.dataset.deal; document.querySelectorAll('[data-deal]').forEach(item => item.classList.toggle('active', item === button)); loadProperties(); })); $('#searchForm').addEventListener('submit', event => { event.preventDefault(); loadProperties(); }); $('#propertyGrid').addEventListener('click', event => { const target = event.target.closest('[data-property]'); if (target) openProperty(target.dataset.property); }); $('#dialogClose').addEventListener('click', () => $('#propertyDialog').close()); $('#propertyDialog').addEventListener('click', event => { if (event.target === $('#propertyDialog')) $('#propertyDialog').close(); }); loadProperties(); });
